"use client";

import * as React from "react";

import {
  AGENT_STATES,
  type AgentState,
} from "@/components/shared/agent-state/engine";
import {
  AgentDots,
  AgentString,
  AgentWaves,
} from "@/components/shared/agent-state/visuals";
import { Card, CardContent } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group";

const STYLES = [
  { id: "dots", label: "Dot matrix", Visual: AgentDots, frame: "size-32" },
  { id: "waves", label: "Waves", Visual: AgentWaves, frame: "h-32 w-full" },
  { id: "string", label: "String", Visual: AgentString, frame: "size-32" },
] as const;

export function AgentStatePreview() {
  return (
    <Tabs defaultValue="states">
      <TabsList>
        <TabsTrigger value="states">Every state</TabsTrigger>
        <TabsTrigger value="switch">Switching</TabsTrigger>
      </TabsList>

      {/* Tabs unmount the hidden panel, which keeps the page under the browser's cap on live WebGL contexts. */}
      <TabsContent value="states">
        <Card>
          <CardContent className="grid grid-cols-[auto_1fr_1fr_1fr] items-center gap-x-6 gap-y-4">
            <span />
            {AGENT_STATES.map((state) => (
              <span
                className="text-center text-sm text-muted-foreground"
                key={state.value}
              >
                {state.label}
              </span>
            ))}
            {STYLES.map(({ id, label, Visual, frame }) => (
              <React.Fragment key={id}>
                <span className="text-sm font-medium">{label}</span>
                {AGENT_STATES.map((state) => (
                  <div className="flex justify-center" key={state.value}>
                    <div className={frame}>
                      <Visual state={state.value} />
                    </div>
                  </div>
                ))}
              </React.Fragment>
            ))}
          </CardContent>
        </Card>
      </TabsContent>

      <TabsContent value="switch">
        <Switching />
      </TabsContent>
    </Tabs>
  );
}

function Switching() {
  const [state, setState] = React.useState<AgentState>("listening");

  return (
    <Card>
      <CardContent className="flex flex-col items-center gap-8">
        <ToggleGroup
          aria-label="Agent state"
          onValueChange={(value) => value && setState(value as AgentState)}
          type="single"
          value={state}
          variant="outline"
        >
          {AGENT_STATES.map((option) => (
            <ToggleGroupItem key={option.value} value={option.value}>
              {option.label}
            </ToggleGroupItem>
          ))}
        </ToggleGroup>

        <div className="grid w-full grid-cols-3 items-center gap-6">
          {STYLES.map(({ id, label, Visual }) => (
            <div className="flex flex-col items-center gap-3" key={id}>
              <div className="h-48 w-full">
                <Visual state={state} />
              </div>
              <span className="text-sm text-muted-foreground">{label}</span>
            </div>
          ))}
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { useEffect, useRef } from "react";

import { classRgb } from "@/components/shared/orb-avatar";
import { cn } from "@/lib/utils";

import {
  AGENT_TONE,
  createShader,
  SHADER_HEAD,
  SHADER_UNIFORMS,
  useAgentLoop,
  type AgentState,
} from "./engine";

type Program = NonNullable<ReturnType<typeof createShader>>;

/** One canvas, one fragment shader, fed the agent's state. */
export function AgentShader({
  body,
  state,
  className,
}: {
  /** GLSL after `SHADER_HEAD`: helpers and `main()`. */
  body: string;
  state: AgentState;
  className?: string;
}) {
  const ref = useRef<HTMLCanvasElement>(null);
  const program = useRef<Program | null>(null);
  const tone = useRef<number[][]>([]);

  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    program.current = createShader(canvas, SHADER_HEAD + body, SHADER_UNIFORMS);
    tone.current = AGENT_TONE.map(classRgb);
    /* No loseContext here: Strict Mode remounts on the same canvas, and a lost context cannot be got back. */
    return () => {
      program.current = null;
    };
  }, [body]);

  useAgentLoop(ref, state, (f) => {
    const p = program.current;
    if (!p || !f.width || !f.height) return;
    const { gl, uniforms: u } = p;
    gl.viewport(0, 0, f.width, f.height);
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);
    gl.uniform2f(u.uRes, f.width, f.height);
    gl.uniform1f(u.uTime, f.time);
    gl.uniform3f(u.uState, f.listen, f.think, f.speak);
    gl.uniform1f(u.uLevel, f.level);
    const [a, b, c] = tone.current;
    gl.uniform3fv(u.uA, a);
    gl.uniform3fv(u.uB, b);
    gl.uniform3fv(u.uC, c);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
  });

  return (
    <canvas aria-hidden className={cn("size-full", className)} ref={ref} />
  );
}

"use client";

import { useEffect, useRef } from "react";

export type AgentState = "listening" | "thinking" | "speaking";

export const AGENT_STATES: { value: AgentState; label: string }[] = [
  { value: "listening", label: "Listening" },
  { value: "thinking", label: "Thinking" },
  { value: "speaking", label: "Speaking" },
];

/** What one picture is drawn from. The three weights sum to 1 and ease between states, so a change of state is a blend, never a cut. */
export type AgentFrame = {
  time: number;
  listen: number;
  think: number;
  speak: number;
  /** 0–1: the caller's voice while listening, the agent's while speaking, nothing while thinking. */
  level: number;
  width: number;
  height: number;
  ratio: number;
};

/* How fast one state hands over to the next: about 400ms to settle. */
const BLEND = 7;

/* How fast the level follows the voice. Higher reads as twitchy. */
const FOLLOW = 14;

/** A speech-like envelope: syllables, words, and the pauses between them. Deterministic, so no two visuals disagree. */
function voice(t: number) {
  const syllable = Math.max(
    0,
    Math.sin(t * 9.1) * 0.6 + Math.sin(t * 5.3) * 0.4,
  );
  const word = 0.55 + 0.45 * Math.sin(t * 1.7 + Math.sin(t * 0.6) * 2);
  const pause = Math.sin(t * 0.83) > -0.55 ? 1 : 0.05;
  return Math.min(1, syllable * word * pause * 1.25);
}

function weights(state: AgentState): [number, number, number] {
  return [
    state === "listening" ? 1 : 0,
    state === "thinking" ? 1 : 0,
    state === "speaking" ? 1 : 0,
  ];
}

/** Sizes the canvas to its box, runs one rAF loop while it is on screen, and hands `draw` a frame. Under reduced motion it draws one still picture per state. */
export function useAgentLoop(
  ref: React.RefObject<HTMLCanvasElement | null>,
  state: AgentState,
  draw: (frame: AgentFrame) => void,
) {
  const target = useRef(weights(state));
  const drawRef = useRef(draw);
  const still = useRef<(() => void) | null>(null);

  useEffect(() => {
    drawRef.current = draw;
  });

  useEffect(() => {
    target.current = weights(state);
    still.current?.();
  }, [state]);

  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;

    const ratio = Math.min(window.devicePixelRatio || 1, 2);
    const resize = () => {
      canvas.width = Math.round(canvas.clientWidth * ratio);
      canvas.height = Math.round(canvas.clientHeight * ratio);
    };
    resize();

    const current = [...target.current] as [number, number, number];
    let level = 0;
    let visible = true;
    let frame = 0;
    let last = performance.now();
    const start = last;

    const paint = (time: number) =>
      drawRef.current({
        time,
        listen: current[0],
        think: current[1],
        speak: current[2],
        level,
        width: canvas.width,
        height: canvas.height,
        ratio,
      });

    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)");
    if (reduce.matches) {
      still.current = () => {
        current.splice(0, 3, ...target.current);
        level = 0.6 * (current[0] * 0.7 + current[2]);
        paint(2);
      };
      still.current();
      const sized = new ResizeObserver(() => {
        resize();
        still.current?.();
      });
      sized.observe(canvas);
      return () => sized.disconnect();
    }

    const tick = (now: number) => {
      const dt = Math.min(0.05, (now - last) / 1000);
      last = now;
      const time = (now - start) / 1000;

      const k = 1 - Math.exp(-dt * BLEND);
      for (let i = 0; i < 3; i++)
        current[i] += (target.current[i] - current[i]) * k;

      /* The caller is quieter than the agent, and a thinking agent hears nothing. */
      const loud =
        current[0] * 0.75 * voice(time * 0.9 + 3) + current[2] * voice(time);
      level += (loud - level) * (1 - Math.exp(-dt * FOLLOW));

      if (visible) paint(time);
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);

    const seen = new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting;
    });
    seen.observe(canvas);
    const sized = new ResizeObserver(resize);
    sized.observe(canvas);

    return () => {
      cancelAnimationFrame(frame);
      seen.disconnect();
      sized.disconnect();
    };
  }, [ref]);
}

/** A full-screen triangle and one fragment shader. Returns the uniform locations by name, or null without WebGL. */
export function createShader(
  canvas: HTMLCanvasElement,
  fragment: string,
  names: string[],
) {
  const gl = canvas.getContext("webgl", { premultipliedAlpha: true });
  if (!gl) return null;

  const compile = (type: number, source: string) => {
    const shader = gl.createShader(type);
    if (!shader) return null;
    gl.shaderSource(shader, source);
    gl.compileShader(shader);
    if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
      console.error(gl.getShaderInfoLog(shader));
      return null;
    }
    return shader;
  };

  const vertex = compile(
    gl.VERTEX_SHADER,
    "attribute vec2 p; void main() { gl_Position = vec4(p, 0.0, 1.0); }",
  );
  const frag = compile(gl.FRAGMENT_SHADER, fragment);
  const program = gl.createProgram();
  if (!vertex || !frag || !program) return null;
  gl.attachShader(program, vertex);
  gl.attachShader(program, frag);
  gl.linkProgram(program);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) return null;
  gl.useProgram(program);

  gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
  gl.bufferData(
    gl.ARRAY_BUFFER,
    new Float32Array([-1, -1, 3, -1, -1, 3]),
    gl.STATIC_DRAW,
  );
  const position = gl.getAttribLocation(program, "p");
  gl.enableVertexAttribArray(position);
  gl.vertexAttribPointer(position, 2, gl.FLOAT, false, 0, 0);

  const uniforms = Object.fromEntries(
    names.map((name) => [name, gl.getUniformLocation(program, name)]),
  );
  return { gl, uniforms };
}

/** The shared GLSL head: the uniforms every agent shader takes, and the orb ramp. */
export const SHADER_HEAD = /* glsl */ `
precision highp float;
uniform vec2 uRes;
uniform float uTime;
uniform vec3 uState;
uniform float uLevel;
uniform vec3 uA;
uniform vec3 uB;
uniform vec3 uC;

vec3 ramp(float t) {
  vec3 col = mix(uA, uB, smoothstep(0.0, 0.5, t));
  return mix(col, uC, smoothstep(0.5, 1.0, t));
}
`;

export const SHADER_UNIFORMS = [
  "uRes",
  "uTime",
  "uState",
  "uLevel",
  "uA",
  "uB",
  "uC",
];

/** The orb's three violets, deepest first — the same light the avatar is made of. */
export const AGENT_TONE = ["bg-orb-deep", "bg-orb-body", "bg-orb-light"];

"use client";

import { useEffect, useRef } from "react";

import { cn } from "@/lib/utils";

import { AgentShader } from "./agent-shader";
import { AGENT_TONE, useAgentLoop, type AgentState } from "./engine";

/* Ten lines of one sine each, staggered in speed — the pasted WaveLines shader, with the
   rainbow swapped for the orb ramp and alpha out so it sits on a light card. Each state
   is a whole displacement, so blending two of them is just a weighted sum. */
const WAVES = /* glsl */ `
void main() {
  vec2 uv = (gl_FragCoord.xy * 2.0 - uRes) / uRes.y;
  float aspect = uRes.x / uRes.y;
  float px = 2.0 / uRes.y;
  float x = uv.x;
  float fade = 1.0 - smoothstep(aspect * 0.5, aspect, abs(x));

  float clear = 1.0;
  vec3 col = vec3(0.0);
  float weight = 0.0;
  for (float layer = 0.0; layer < 1.0; layer += 0.1) {
    /* Listening: the lines meet at the ends and part in the middle, like a lens that
       opens as the caller speaks, with a slow sway so it never sits dead still. */
    float lens = exp(-x * x * 1.4);
    float dL = (layer - 0.45) * (0.24 + 0.9 * uLevel) * lens
      + 0.05 * sin(1.6 * x - uTime * 0.9 + layer * 1.5) * lens;

    /* Thinking: flat, with one packet of ripple running along the lines. */
    float head = mod(uTime * 1.1 + layer * 0.35, 2.0 * aspect + 1.2) - aspect - 0.6;
    float dT = 0.22 * exp(-(x - head) * (x - head) * 4.84)
      * sin(7.0 * x - uTime * 3.0 * (1.0 - layer * 0.7) + layer * 2.4);

    /* Speaking: tall and quick, driven by the agent's voice. */
    float dS = (0.06 + 0.6 * uLevel) * (1.0 - layer * 0.5)
      * (0.6 + 0.4 * sin(uTime * 1.3 + layer * 5.0))
      * sin(3.2 * x - uTime * 2.0 * (1.0 - layer * 0.7) - layer * 2.4);

    float y = uv.y - (uState.x * dL + uState.y * dT + uState.z * dS);
    float b = 1.0 - smoothstep(0.0, 1.5 * px, abs(y));
    clear *= 1.0 - 0.6 * b;
    col += ramp(0.1 + 0.4 * layer) * b;
    weight += b;
  }

  float a = (1.0 - clear) * fade;
  gl_FragColor = vec4(col / max(weight, 1e-4) * a, a);
}
`;

/* Six fine strands on one ring, each drawn at partial opacity so where they cross reads
   denser. Listening is a loose skein that opens with the caller; thinking twists the
   strands into a rope with one bright arc running round it; speaking plucks the higher
   harmonics, each strand out of phase, so a loud voice frays the ring. */
const STRING = /* glsl */ `
void main() {
  float side = min(uRes.x, uRes.y);
  vec2 uv = (gl_FragCoord.xy * 2.0 - uRes) / side;
  float px = 2.0 / side;
  float r = length(uv);
  float a = atan(uv.y, uv.x);

  float clear = 1.0;
  vec3 col = vec3(0.0);
  float weight = 0.0;
  for (int i = 0; i < 6; i++) {
    float s = float(i) / 5.0;
    float o = float(i) * 1.0472;

    float rL = 0.6 + 0.05 * uLevel
      + (0.045 + 0.14 * uLevel) * sin(2.0 * a + uTime * 0.7 + o)
      + 0.025 * sin(3.0 * a - uTime * 0.5 + o * 2.0);
    float rT = 0.56 + 0.07 * sin(3.0 * a - uTime * 2.4 + o);
    float rS = 0.6 + (0.02 + 0.16 * uLevel)
      * (0.6 * sin(5.0 * a + uTime * 2.4 + o) + 0.4 * sin(3.0 * a - uTime * 1.6 + o * 1.7));

    float radius = uState.x * rL + uState.y * rT + uState.z * rS;
    float b = 1.0 - smoothstep(0.0, 1.2 * px, abs(r - radius));

    float trail = mod(a - uTime * 2.6, 6.2832);
    b *= mix(1.0, 0.25 + 0.75 * exp(-trail * 0.5), uState.y);

    clear *= 1.0 - 0.55 * b;
    col += ramp(0.05 + 0.5 * s) * b;
    weight += b;
  }

  float alpha = 1.0 - clear;
  gl_FragColor = vec4(col / max(weight, 1e-4) * alpha, alpha);
}
`;

export function AgentWaves({
  state,
  className,
}: {
  state: AgentState;
  className?: string;
}) {
  return <AgentShader body={WAVES} className={className} state={state} />;
}

export function AgentString({
  state,
  className,
}: {
  state: AgentState;
  className?: string;
}) {
  return <AgentShader body={STRING} className={className} state={state} />;
}

/* A 5 x 5 loader: fixed small dots, a few steps of opacity, time moving in steps. */
const GRID = 5;
const DOT = 6;
const PITCH = 10;
const STEPS = 9; // per second

/* The outer ring clockwise from the top-left, and the inner ring the same way. */
const OUTER = [
  [0, 0],
  [1, 0],
  [2, 0],
  [3, 0],
  [4, 0],
  [4, 1],
  [4, 2],
  [4, 3],
  [4, 4],
  [3, 4],
  [2, 4],
  [1, 4],
  [0, 4],
  [0, 3],
  [0, 2],
  [0, 1],
];
const INNER = [
  [1, 1],
  [2, 1],
  [3, 1],
  [3, 2],
  [3, 3],
  [2, 3],
  [1, 3],
  [1, 2],
];

/* Trail behind a head running round a ring: the head, then fading. */
function orbit(ring: number[][], head: number, trail: number[]) {
  const out = new Map<string, number>();
  trail.forEach((v, back) => {
    const [x, y] =
      ring[(((head - back) % ring.length) + ring.length) % ring.length];
    out.set(`${x},${y}`, v);
  });
  return out;
}

/** Five by five. Listening draws rings inward, thinking runs two dots round in opposite directions, speaking is a mirrored level meter. */
export function AgentDots({
  state,
  className,
}: {
  state: AgentState;
  className?: string;
}) {
  const ref = useRef<HTMLCanvasElement>(null);
  const ink = useRef("");

  useEffect(() => {
    const swatch = document.createElement("span");
    swatch.className = `${AGENT_TONE[0]} hidden`;
    document.body.append(swatch);
    ink.current = getComputedStyle(swatch).backgroundColor;
    swatch.remove();
  }, []);

  useAgentLoop(ref, state, (f) => {
    const context = ref.current?.getContext("2d");
    if (!context) return;
    context.clearRect(0, 0, f.width, f.height);
    context.fillStyle = ink.current;

    const step = Math.floor(f.time * STEPS);
    const pitch = PITCH * f.ratio;
    const ox = f.width / 2 - pitch * 2;
    const oy = f.height / 2 - pitch * 2;

    /* Listening: one ring lit at a time, outer to centre, as loud as the caller. */
    const ring = 2 - (Math.floor(step / 3) % 3);
    const loud = 0.35 + 0.65 * Math.min(1, f.level * 1.6);

    /* Thinking. */
    const outer = orbit(OUTER, step, [1, 0.7, 0.45, 0.25]);
    const inner = orbit(INNER, -Math.floor(step / 2), [0.85, 0.4]);

    for (let row = 0; row < GRID; row++) {
      for (let col = 0; col < GRID; col++) {
        const d = Math.max(Math.abs(col - 2), Math.abs(row - 2));
        const listen = (d === ring ? 1 : d === (ring + 1) % 3 ? 0.4 : 0) * loud;

        const key = `${col},${row}`;
        const think = outer.get(key) ?? inner.get(key) ?? 0;

        /* Speaking: each column a bar mirrored about the middle row; silence is a flat line. */
        const shape = [0.45, 0.8, 1, 0.8, 0.45][col];
        const wobble = 0.7 + 0.3 * Math.sin(f.time * 11 + col * 1.9);
        const height = f.level * shape * wobble * 2.6;
        const reach = Math.abs(row - 2);
        const speak =
          reach === 0
            ? 0.45 + 0.55 * Math.min(1, height * 2)
            : Math.min(1, Math.max(0, height - reach + 1)) * (1 - reach * 0.15);

        const v = Math.min(
          1,
          f.listen * listen + f.think * think + f.speak * speak,
        );
        /* Five steps of opacity, so it reads as a matrix, not a gradient. */
        context.globalAlpha = 0.12 + 0.88 * (Math.round(v * 4) / 4);
        context.beginPath();
        context.arc(
          ox + col * pitch,
          oy + row * pitch,
          (DOT / 2) * f.ratio,
          0,
          Math.PI * 2,
        );
        context.fill();
      }
    }
    context.globalAlpha = 1;
  });

  return (
    <canvas aria-hidden className={cn("size-full", className)} ref={ref} />
  );
}

"use client";

import { useEffect, useRef } from "react";

import { TONES, type OrbTone } from "@/components/shared/orb-tones";
import { Avatar } from "@/components/ui/avatar";

/** One shared offscreen WebGL context draws every avatar: browsers cap live contexts at around sixteen. */

type Rgb = [number, number, number];

/* How far toward white the body and the light sit, for a one-token tone. */
const BODY = 0.4;
const LIGHT = 0.75;

function toward(rgb: Rgb, amount: number): Rgb {
  return rgb.map((c) => c + (1 - c) * amount) as Rgb;
}

function toneRgb(tone: OrbTone): Rgb[] {
  const stops: readonly string[] = TONES[tone];
  const [deep, body, light] = stops.map(classRgb);
  return [deep, body ?? toward(deep, BODY), light ?? toward(deep, LIGHT)];
}

const VERTEX = `
attribute vec2 p;
void main() { gl_Position = vec4(p, 0.0, 1.0); }
`;

const FRAGMENT = `
precision highp float;
uniform vec2 uRes;
uniform float uSeed;
uniform float uTime;
uniform vec3 uA;
uniform vec3 uB;
uniform vec3 uC;

/* How many cells run across the disc: fine enough to read as a texture, and
   still about five device pixels a cell on a 24px avatar. */
const float CELLS = 9.0;

/* How strongly each cell flips and magnifies the light behind it. */
const float LENS = 0.6;

/* The light: one bright blob and one deep one, drifting on their own slow
   orbits. The seed sets where each starts, so every name is at a different
   point on the same loop. */
float field(vec2 p) {
  vec2 bright = vec2(cos(uSeed + uTime * 0.7), sin(uSeed * 1.3 + uTime * 0.5)) * 0.55;
  vec2 deep = vec2(cos(uSeed + 2.6 - uTime * 0.4), sin(uSeed * 0.7 + 2.6 + uTime * 0.6)) * 0.45;
  float f = 0.5
    + 0.7 * smoothstep(1.6, 0.0, length(p - bright))
    - 0.6 * smoothstep(1.2, 0.0, length(p - deep));
  return clamp(f, 0.0, 1.0);
}

vec3 ramp(float f) {
  vec3 col = mix(uA, uB, smoothstep(0.0, 0.55, f));
  return mix(col, uC, smoothstep(0.45, 1.0, f));
}

void main() {
  vec2 uv = (gl_FragCoord.xy * 2.0 - uRes) / uRes.y;
  float mask = 1.0 - smoothstep(1.0 - 4.0 / uRes.y, 1.0, length(uv));
  if (mask <= 0.0) {
    gl_FragColor = vec4(0.0);
    return;
  }

  /* A square grid turned 45 degrees, so the cells are diamonds and the
     lines between them run on the diagonals. */
  mat2 turn = mat2(0.7071, -0.7071, 0.7071, 0.7071);
  mat2 back = mat2(0.7071, 0.7071, -0.7071, 0.7071);
  vec2 g = turn * uv * CELLS * 0.5;
  vec2 cell = fract(g) - 0.5;

  /* Each cell is a lens: it shows the light behind its own centre, flipped
     and magnified, which is what makes the lattice read as liquid glass
     rather than a pattern printed on top. */
  vec2 offset = back * cell * (2.0 / CELLS);
  float f = field(uv - offset * (1.0 + LENS));
  vec3 col = ramp(f);

  /* The bevel: each diamond catches light on its upper-left faces and falls
     into shade on the lower-right, strongest at the rim. */
  float d = max(abs(cell.x), abs(cell.y));
  vec2 face = back * (abs(cell.x) > abs(cell.y) ? vec2(sign(cell.x), 0.0) : vec2(0.0, sign(cell.y)));
  float lit = dot(face, vec2(-0.7071, 0.7071));
  col += smoothstep(0.2, 0.5, d) * lit * 0.08;

  /* The groove between cells, drawn a step deeper on the ramp than the
     light it runs through, so it shows on the pale side and sinks on the
     deep side the way a real channel would. */
  float aa = 1.5 * CELLS / uRes.y;
  float groove = smoothstep(0.5 - 2.5 * aa, 0.5, d);
  col = mix(col, ramp(f * 0.7), groove * 0.55);

  gl_FragColor = vec4(col * mask, mask);
}
`;

type Renderer = {
  gl: WebGLRenderingContext;
  uniforms: Record<
    "res" | "seed" | "time" | "a" | "b" | "c",
    WebGLUniformLocation | null
  >;
};

let renderer: Renderer | null | undefined;

function compile(gl: WebGLRenderingContext, type: number, source: string) {
  const shader = gl.createShader(type);
  if (!shader) return null;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  return gl.getShaderParameter(shader, gl.COMPILE_STATUS) ? shader : null;
}

function getRenderer(): Renderer | null {
  if (renderer !== undefined) return renderer;
  renderer = null;

  const gl = document.createElement("canvas").getContext("webgl", {
    premultipliedAlpha: true,
  });
  if (!gl) return null;

  const vertex = compile(gl, gl.VERTEX_SHADER, VERTEX);
  const fragment = compile(gl, gl.FRAGMENT_SHADER, FRAGMENT);
  const program = gl.createProgram();
  if (!vertex || !fragment || !program) return null;
  gl.attachShader(program, vertex);
  gl.attachShader(program, fragment);
  gl.linkProgram(program);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) return null;
  gl.useProgram(program);

  gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
  gl.bufferData(
    gl.ARRAY_BUFFER,
    new Float32Array([-1, -1, 3, -1, -1, 3]),
    gl.STATIC_DRAW,
  );
  const position = gl.getAttribLocation(program, "p");
  gl.enableVertexAttribArray(position);
  gl.vertexAttribPointer(position, 2, gl.FLOAT, false, 0, 0);

  renderer = {
    gl,
    uniforms: {
      res: gl.getUniformLocation(program, "uRes"),
      seed: gl.getUniformLocation(program, "uSeed"),
      time: gl.getUniformLocation(program, "uTime"),
      a: gl.getUniformLocation(program, "uA"),
      b: gl.getUniformLocation(program, "uB"),
      c: gl.getUniformLocation(program, "uC"),
    },
  };
  return renderer;
}

// A hidden element wearing the class resolves the colour (possibly oklch or lab), and a 2D canvas turns it into sRGB.
let probe: CanvasRenderingContext2D | null = null;

export function classRgb(className: string): Rgb {
  probe ??= document
    .createElement("canvas")
    .getContext("2d", { willReadFrequently: true });
  if (!probe) return [0.5, 0.5, 0.5];

  const swatch = document.createElement("span");
  swatch.className = `${className} hidden`;
  document.body.append(swatch);
  const value = getComputedStyle(swatch).backgroundColor;
  swatch.remove();

  probe.clearRect(0, 0, 1, 1);
  probe.fillStyle = value;
  probe.fillRect(0, 0, 1, 1);
  const [r, g, b] = probe.getImageData(0, 0, 1, 1).data;
  return [r / 255, g / 255, b / 255];
}

function hash(value: string) {
  let h = 2166136261;
  for (const char of value)
    h = Math.imul(h ^ char.charCodeAt(0), 16777619) >>> 0;
  return h;
}

type Orb = {
  canvas: HTMLCanvasElement;
  context: CanvasRenderingContext2D;
  seed: number;
  colours: [number, number, number][];
  visible: boolean;
};

const orbs = new Set<Orb>();
let frame = 0;
const start = typeof performance === "undefined" ? 0 : performance.now();

// Seconds of drift per real second.
const SPEED = 0.35;

function paint(orb: Orb, time: number) {
  const r = getRenderer();
  if (!r) return;
  const { gl, uniforms } = r;
  const { width, height } = orb.canvas;
  if (!width || !height) return;

  const glCanvas = gl.canvas as HTMLCanvasElement;
  if (glCanvas.width < width || glCanvas.height < height) {
    glCanvas.width = Math.max(glCanvas.width, width);
    glCanvas.height = Math.max(glCanvas.height, height);
  }

  gl.viewport(0, 0, width, height);
  gl.clearColor(0, 0, 0, 0);
  gl.clear(gl.COLOR_BUFFER_BIT);
  gl.uniform2f(uniforms.res, width, height);
  gl.uniform1f(uniforms.seed, orb.seed);
  gl.uniform1f(uniforms.time, time);
  gl.uniform3fv(uniforms.a, orb.colours[0]);
  gl.uniform3fv(uniforms.b, orb.colours[1]);
  gl.uniform3fv(uniforms.c, orb.colours[2]);
  gl.drawArrays(gl.TRIANGLES, 0, 3);

  /* The viewport sits at the bottom of the GL canvas, which may be taller
     than this avatar, so copy from that corner. */
  orb.context.clearRect(0, 0, width, height);
  orb.context.drawImage(
    glCanvas,
    0,
    glCanvas.height - height,
    width,
    height,
    0,
    0,
    width,
    height,
  );
}

function tick(now: number) {
  const time = ((now - start) / 1000) * SPEED;
  for (const orb of orbs) if (orb.visible) paint(orb, time);
  frame = orbs.size ? requestAnimationFrame(tick) : 0;
}

type OrbAvatarProps = React.ComponentProps<typeof Avatar> & {
  /** Who it stands for. Read out to screen readers and used as the seed. */
  name: string;
  tone?: OrbTone;
};

export function OrbAvatar({
  name,
  tone = "violet",
  children,
  ...props
}: OrbAvatarProps) {
  const ref = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = ref.current;
    const context = canvas?.getContext("2d");
    if (!canvas || !context) return;

    const ratio = window.devicePixelRatio || 1;
    canvas.width = Math.round(canvas.clientWidth * ratio);
    canvas.height = Math.round(canvas.clientHeight * ratio);

    const h = hash(name);
    const orb: Orb = {
      canvas,
      context,
      seed: ((h >>> 4) % 997) / 7,
      colours: toneRgb(tone),
      visible: true,
    };

    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      paint(orb, 0);
      return;
    }

    const observer = new IntersectionObserver(([entry]) => {
      orb.visible = entry.isIntersecting;
    });
    observer.observe(canvas);

    orbs.add(orb);
    frame ||= requestAnimationFrame(tick);

    return () => {
      observer.disconnect();
      orbs.delete(orb);
      if (!orbs.size) {
        cancelAnimationFrame(frame);
        frame = 0;
      }
    };
  }, [name, tone]);

  return (
    <Avatar {...props}>
      <canvas
        aria-label={name}
        className="size-full rounded-full"
        ref={ref}
        role="img"
      />
      {children}
    </Avatar>
  );
}

/** Kept out of orb-avatar.tsx: a server page importing a value from a client module gets a reference, not the array. Written as classes so Tailwind emits the colour variables. */
export const TONES = {
  violet: ["bg-orb-deep", "bg-orb-body", "bg-orb-light"],
  brand: ["bg-primary"],
  blue: ["bg-chart-2"],
  teal: ["bg-chart-3"],
  amber: ["bg-chart-4"],
  rose: ["bg-chart-5"],
} as const;

export type OrbTone = keyof typeof TONES;
export const ORB_TONES = Object.keys(TONES) as OrbTone[];

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
